def t(key, lang=DEFAULT_LANGUAGE):
    return TRANSLATIONS.get(lang, TRANSLATIONS[DEFAULT_LANGUAGE]).get(key, key)


def periodicity_label(key, lang=DEFAULT_LANGUAGE):
    return PERIODICITY_LABELS.get(lang, PERIODICITY_LABELS[DEFAULT_LANGUAGE])[key]


def periodicity_key(label, lang=DEFAULT_LANGUAGE):
    labels = PERIODICITY_LABELS.get(lang, PERIODICITY_LABELS[DEFAULT_LANGUAGE])
    return next((k for k, v in labels.items() if v == label), None)


def difficulty_label(key, lang=DEFAULT_LANGUAGE):
    return DIFFICULTY_LABELS.get(lang, DIFFICULTY_LABELS[DEFAULT_LANGUAGE])[key]


def difficulty_key(label, lang=DEFAULT_LANGUAGE):
    labels = DIFFICULTY_LABELS.get(lang, DIFFICULTY_LABELS[DEFAULT_LANGUAGE])
    return next((k for k, v in labels.items() if v == label), None)
